package ru.neverland.mintespionage.service;
import java.util.*;import java.util.concurrent.*;import org.bukkit.Bukkit;import org.bukkit.plugin.java.JavaPlugin;import ru.neverland.core.*;import static ru.neverland.mintespionage.service.SpyPurchases.*;
/** Independent purchase ACK, Treasury ACK, and mission/level ACK. Unknown bank replies keep one identity. */
public final class SpyPurchaseController {
    private final JavaPlugin plugin;private final EspionageRepository core;private final SpyPurchaseRepository ledger;private final EconomyService economy;private final java.util.function.Predicate<Terms> allowed,impossible;
    private CompletionStage<?> active=CompletableFuture.completedFuture(null);private CompletionStage<Void> close;private boolean closing;private int cursor;private long warned;
    public SpyPurchaseController(JavaPlugin plugin,EspionageRepository core,SpyPurchaseRepository ledger,EconomyService economy,java.util.function.Predicate<Terms> allowed,java.util.function.Predicate<Terms> impossible){this.plugin=plugin;this.core=core;this.ledger=ledger;this.economy=economy;this.allowed=allowed;this.impossible=impossible;}
    public boolean ready(){return !closing&&ledger.writable()&&!ledger.busy()&&!busy()&&ledger.state().entries().size()<MAX;}
    public boolean busy(){return !active.toCompletableFuture().isDone();}
    public boolean pending(UUID town){return ledger.state().entries().values().stream().anyMatch(p->p.pending()&&p.terms().town().equals(town));}
    public void submit(Terms terms){if(!ready()||pending(terms.town()))throw new IllegalStateException("Предыдущая покупка разведки ещё обрабатывается");track(ledger.put(new Purchase(terms,Phase.PREPARED)).whenComplete((v,error)->{if(error!=null)message(terms,"Покупку не удалось сохранить. Новое списание не начиналось; обратитесь к администратору.");}));}
    public void pulse(){if(closing||busy()||ledger.busy()||!ledger.writable()||!core.canMutate()||SuiteState.frozen(plugin.getName()))return;var pending=ledger.state().entries().values().stream().filter(Purchase::pending).sorted(Comparator.comparing(p->p.terms().id())).toList();if(pending.isEmpty())return;var p=pending.get(Math.floorMod(cursor++,pending.size()));var t=p.terms();try{
        if(p.phase()==Phase.REFUND_PENDING){if(core.purchaseApplied(t))throw new IllegalStateException("Уже применённая покупка не может быть возвращена "+t.id());if(t.cents()==0){track(ledger.put(p.phase(Phase.REFUNDED)));return;}track(economy.refund(p).thenCompose(row->{try(var guard=SuiteState.guard()){if(closing)return CompletableFuture.completedFuture(null);if(!p.equals(ledger.state().entries().get(t.id())))return CompletableFuture.failedFuture(new IllegalStateException("Возврат изменился до ответа казны"));return switch((String)row.get("status")){case "PAID"->ledger.put(p.phase(Phase.REFUNDED)).thenApply(v->{message(t,"Покупка отменена; казна подтвердила полный возврат.");return null;});case "REJECTED"->ledger.put(p.rejectedRefund()).thenApply(v->null);case "PREPARED","INVOKING","REVIEW"->CompletableFuture.completedFuture(null);default->CompletableFuture.failedFuture(new IllegalStateException("Неизвестное состояние возврата"));};}}));return;}
        if(p.phase()==Phase.PAID){if(core.purchaseApplied(t)){track(ledger.put(p.phase(Phase.APPLIED)));return;}if(impossible.test(t)){track(ledger.put(p.phase(Phase.REFUND_PENDING)));return;}if(!allowed.test(t))return;track(core.applyPurchase(p,System.currentTimeMillis()).thenCompose(v->{try(var guard=SuiteState.guard()){if(closing)return CompletableFuture.completedFuture(null);return ledger.put(p.phase(Phase.APPLIED)).thenApply(done->{message(t,t.kind()==Kind.MISSION?"Оплата подтверждена. Разведывательная миссия началась.":"Оплата подтверждена. Уровень разведки повышен до "+(t.fromLevel()+1)+".");return null;});}}));return;}
        if(t.cents()==0){if(allowed.test(t)||impossible.test(t))track(ledger.put(p.phase(Phase.PAID)));return;}
        var known=economy.status(t);CompletionStage<Map<?,?>> response;if("ABSENT".equals(known.get("status"))){/* active request stage is finished and Suite excludes a concurrent submit; exact gateway ABSENT proves no durable pre-bank intent. */if(impossible.test(t)){track(ledger.put(p.phase(Phase.CANCELLED)));return;}if(!allowed.test(t))return;response=economy.request(t);}else response=CompletableFuture.completedFuture(known);
        track(response.thenCompose(row->{try(var guard=SuiteState.guard()){if(closing)return CompletableFuture.completedFuture(null);var current=ledger.state().entries().get(t.id());if(!p.equals(current))return CompletableFuture.failedFuture(new IllegalStateException("Покупка изменилась до ответа казны"));String status=(String)row.get("status");return switch(status){case "PAID"->ledger.put(p.phase(Phase.PAID)).thenApply(v->null);case "REJECTED"->ledger.put(p.phase(Phase.REJECTED)).thenApply(v->{message(t,"Казна отклонила оплату. Миссия или улучшение не начаты; квитанция "+t.id()+".");return null;});case "PREPARED","INVOKING","REVIEW"->CompletableFuture.completedFuture(null);default->CompletableFuture.failedFuture(new IllegalStateException("Неизвестный ответ казны"));};}}));
    }catch(Exception error){warn(error);}}
    public CompletionStage<?> requestRefund(UUID town,UUID id){try(var guard=SuiteState.guard()){if(closing||!ledger.writable()||ledger.busy()||busy()||!core.canMutate())throw new IllegalStateException("Дождитесь завершения сохранения покупки");var p=ledger.state().entries().get(id);if(p==null||town!=null&&!p.terms().town().equals(town))throw new IllegalArgumentException("Покупка не найдена в вашем городе");if(core.purchaseApplied(p.terms()))throw new IllegalStateException("Покупка уже исполнена; возврат не разрешён");if(p.phase()==Phase.REFUND_PENDING||p.phase()==Phase.REFUNDED)return CompletableFuture.completedFuture(null);if(p.phase()!=Phase.PAID)throw new IllegalStateException("Сначала дождитесь ответа казны или сверки банковской квитанции; неизвестное списание не возвращается вслепую");var stage=ledger.put(p.phase(Phase.REFUND_PENDING));track(stage);return stage;}}
    public String diagnostic(){return !ledger.writable()?"Журнал покупок недоступен; принятые миссии сохранены":!economy.purchaseAvailable()?"Платные покупки недоступны: нужен работающий NeverLandTownyTreasuryPlus с requestDebit":"Подтверждаемая оплата доступна; ожидают: "+ledger.state().entries().values().stream().filter(Purchase::pending).count();}
    public Optional<Purchase> find(UUID id){return Optional.ofNullable(ledger.state().entries().get(id));}
    public List<Purchase> history(UUID town){return ledger.state().entries().values().stream().filter(p->town==null||p.terms().town().equals(town)).sorted(Comparator.comparing((Purchase p)->!p.pending()).thenComparing(Comparator.comparingLong((Purchase p)->p.terms().created()).reversed())).limit(30).toList();}
    public static String label(Phase p){return switch(p){case PREPARED->"Ожидается ответ казны или сверка";case PAID->"Оплачено; ожидается запуск или сохранение";case APPLIED->"Завершено";case REJECTED->"Оплата отклонена";case CANCELLED->"Отменено до оплаты";case REFUND_PENDING->"Возврат ожидает казну или сверку";case REFUNDED->"Покупка отменена; средства возвращены";};}
    private void track(CompletionStage<?> stage){active=stage;stage.whenComplete((v,error)->{if(error!=null)warn(error);});}
    private void warn(Throwable error){long now=System.currentTimeMillis();if(now-warned<60000)return;warned=now;plugin.getLogger().log(java.util.logging.Level.WARNING,"Покупка разведки ожидает восстановления или сверки. Сохранённый ID не меняется",error);}
    private void message(Terms t,String text){if(closing)return;var player=Bukkit.getPlayer(t.actor());if(player!=null)SuiteScheduler.entity(plugin,player,()->player.sendMessage("§e[Разведка] "+text));}
    public CompletionStage<Void> prepareClose(){try(var guard=SuiteState.guard()){if(close==null){closing=true;close=active.handle((v,e)->null).thenCompose(v->ledger.prepareClose());}return close;}}
}
